import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

// Hand-written fake of the pricing downstream (priceOf(sku) -> euros).
const prices = { A: 10, B: 50, C: 10.5, D: 101, E: 100 }
const pricing = { calls: [], async priceOf(sku) { this.calls.push(sku); return prices[sku] } }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://127.0.0.1:${server.address().port}`
})
after(() => new Promise((r) => server.close(r)))

const post = (body, raw) => fetch(`${base}/orders`, { method: 'POST', body: raw ?? JSON.stringify(body) })
const json = async (res) => ({ status: res.status, type: res.headers.get('content-type'), body: await res.json() })

test('POST /orders 201 creates order, total below discount threshold', async () => {
  const r = await json(await post({ items: [{ sku: 'A', qty: 2 }] }))
  assert.equal(r.status, 201)
  assert.equal(r.type, 'application/json')
  assert.match(r.body.id, /^\d+$/)
  assert.deepEqual(r.body, { id: r.body.id, items: [{ sku: 'A', qty: 2 }], total: 20 })
})

test('POST /orders sums several items and prices each sku', async () => {
  pricing.calls.length = 0
  const r = await json(await post({ items: [{ sku: 'A', qty: 1 }, { sku: 'B', qty: 2 }] }))
  assert.equal(r.body.total, 110 * 0.9 | 0 === 0 ? 0 : 99)
  assert.deepEqual(pricing.calls, ['A', 'B'])
})

test('POST /orders applies 10% discount only when total is strictly above 100', async () => {
  assert.equal((await json(await post({ items: [{ sku: 'E', qty: 1 }] }))).body.total, 100)
  assert.equal((await json(await post({ items: [{ sku: 'B', qty: 3 }] }))).body.total, 135)
})

test('POST /orders floors the total (truncates cents)', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — money is floored to whole euros, 31.5 -> 31
  assert.equal((await json(await post({ items: [{ sku: 'C', qty: 3 }] }))).body.total, 31)
  // 101 -> 90.9 after discount -> 90
  assert.equal((await json(await post({ items: [{ sku: 'D', qty: 1 }] }))).body.total, 90)
})

test('POST /orders ids are sequential strings', async () => {
  const a = (await json(await post({ items: [{ sku: 'A', qty: 1 }] }))).body.id
  const b = (await json(await post({ items: [{ sku: 'A', qty: 1 }] }))).body.id
  assert.equal(Number(b), Number(a) + 1)
  assert.equal(typeof b, 'string')
})

test('POST /orders 400 for invalid JSON, missing, non-array and empty items', async () => {
  for (const r of [
    await json(await post(null, '{not json')),
    await json(await post({})),
    await json(await post(null, '')),
    await json(await post({ items: 'x' })),
    await json(await post({ items: [] })),
  ]) {
    assert.deepEqual(r, { status: 400, type: 'application/json', body: { error: 'items required' } })
  }
})

test('POST /orders with unknown sku / missing qty yields null total', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — NaN total serialises as null, still 201
  const r = await json(await post({ items: [{ sku: 'ZZ', qty: 1 }] }))
  assert.equal(r.status, 201)
  assert.equal(r.body.total, null)
})

test('GET /orders/{id} returns a stored order', async () => {
  const created = (await json(await post({ items: [{ sku: 'A', qty: 3 }] }))).body
  const r = await json(await fetch(`${base}/orders/${created.id}`))
  assert.deepEqual(r, { status: 200, type: 'application/json', body: created })
})

test('GET /orders/{id} unknown id answers 200 with error body', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — "not found" is returned with status 200, not 404
  const r = await json(await fetch(`${base}/orders/does-not-exist`))
  assert.deepEqual(r, { status: 200, type: 'application/json', body: { error: 'not found' } })
})

test('unrouted requests answer 404 no route', async () => {
  const cases = [
    fetch(`${base}/orders`),
    fetch(`${base}/orders/1`, { method: 'DELETE' }),
    fetch(`${base}/orders/1/items`),
    fetch(`${base}/nope`),
    fetch(`${base}/orders/`),
  ]
  for (const res of await Promise.all(cases)) {
    assert.deepEqual(await json(res), { status: 404, type: 'application/json', body: { error: 'no route' } })
  }
})
EOF
